import{_ as a,o as i,a as t,b as l}from"./app.DKoEZOcr.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"寄存器数据类型","link":"/api/SIMD-API/basic_api/reg_vector_compute/register_data_types/register_data_types"},{"text":"UnalignRegForLoad & UnalignRegForStore","link":"/api/SIMD-API/basic_api/reg_vector_compute/register_data_types/UnalignRegForLoad-UnalignRegForStore"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/UnalignRegForLoad-UnalignRegForStore.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/UnalignRegForLoad-UnalignRegForStore.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"支持的型号","slug":"支持的型号","link":"#支持的型号"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1788159000000}'),n={name:"api/SIMD-API/basic_api/reg_vector_compute/register_data_types/UnalignRegForLoad-UnalignRegForStore.md"};function r(o,e,s,d,g,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>UnalignRegForLoad &amp; UnalignRegForStore<span id="ZH-CN_TOPIC_0000001956862301"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>为提升对不规则内存地址的处理能力，Reg矢量计算支持在数据搬运过程中对非32字节对齐的地址进行访问，适用于从Unified Buffer（UB）向RegTensor非对齐搬运，或从RegTensor向UB非对齐搬运的场景。RegBase引入非对齐寄存器缓存机制，降低非对齐访问带来的性能开销，该机制利用非对齐寄存器（32B）UnalignRegForLoad和UnalignRegForStore作为临时缓存区，用于暂存非32B对齐的数据，从而实现高效的连续非对齐数据传输。</p><ul><li><p>UnalignRegForLoad为非对齐搬入寄存器，在读非对齐地址时，先通过LoadUnAlignPre进行初始化（将非对齐地址数据暂存进UnalignRegForLoad），再调用LoadUnAlign进行搬运。</p></li><li><p>UnalignRegForStore为非对齐搬出寄存器，在写非对齐地址时，先调用StoreUnAlign，再使用StoreUnAlignPost进行后处理（将UnalignRegForStore中的数据写入非对齐UB地址）。</p></li></ul><p>UnalignRegForLoad和UnalignRegForStore的具体使用方式请参考：<a href="../reg_data_load/LoadUnAlign_continuous.html">连续非对齐搬入（LoadUnAlign）</a>、<a href="../reg_data_store/StoreUnAlign_continuous.html">连续非对齐搬出（StoreUnAlign）</a>。</p><h2 id="支持的型号">支持的型号<span id="section156721693504"></span><a class="header-anchor" href="#支持的型号">​</a></h2><p>Ascend 950PR/Ascend 950DT</p><h2 id="约束说明">约束说明<span id="section11585101304320"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>UnalignRegForLoad寄存器数量上限为4，超出后编译器将报错。</p></li><li><p>UnalignRegForStore寄存器数量上限为4，超出后编译器将报错。</p></li></ul></article></div>',1)])])}const A=a(n,[["render",r]]);export{c as __pageData,A as default};
